{
  "items": [
    {
      "name": "Nat.sqrt_lt'",
      "module_name": "Mathlib.Data.Nat.Sqrt",
      "kind": "theorem",
      "type": "∀ {m n : ℕ}, m.sqrt < n ↔ m < n ^ 2"
    },
    {
      "name": "Nat.sqrt_lt",
      "module_name": "Mathlib.Data.Nat.Sqrt",
      "kind": "theorem",
      "type": "∀ {m n : ℕ}, m.sqrt < n ↔ m < n * n"
    },
    {
      "name": "Nat.exists_mul_self'",
      "module_name": "Mathlib.Data.Nat.Sqrt",
      "kind": "theorem",
      "type": "∀ (x : ℕ), (∃ n, n ^ 2 = x) ↔ x.sqrt ^ 2 = x"
    },
    {
      "name": "bertrand_main_inequality",
      "module_name": "Mathlib.NumberTheory.Bertrand",
      "kind": "theorem",
      "type": "∀ {n : ℕ}, 512 ≤ n → n * (2 * n) ^ (2 * n).sqrt * 4 ^ (2 * n / 3) ≤ 4 ^ n"
    },
    {
      "name": "Nat.minFac_lemma",
      "module_name": "Mathlib.Data.Nat.Prime.Defs",
      "kind": "theorem",
      "type": "∀ (n k : ℕ), ¬n < k * k → n.sqrt - k < n.sqrt + 2 - k"
    },
    {
      "name": "Real.nat_sqrt_le_real_sqrt",
      "module_name": "Mathlib.Data.Real.Sqrt",
      "kind": "theorem",
      "type": "∀ {a : ℕ}, ↑a.sqrt ≤ √↑a"
    },
    {
      "name": "Int.lt_of_sum_four_squares_eq_mul",
      "module_name": "Mathlib.NumberTheory.SumFourSquares",
      "kind": "theorem",
      "type": "∀ {a b c d k m : ℕ}, a ^ 2 + b ^ 2 + c ^ 2 + d ^ 2 = k * m → 2 * a < m → 2 * b < m → 2 * c < m → 2 * d < m → k < m"
    },
    {
      "name": "Real.real_sqrt_le_nat_sqrt_succ",
      "module_name": "Mathlib.Data.Real.Sqrt",
      "kind": "theorem",
      "type": "∀ {a : ℕ}, √↑a ≤ ↑a.sqrt + 1"
    }
  ]
}
